using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.XR.Interaction.Toolkit.Interactables;
namespace ChemistryLab {
public static class SafetyStationBuilder {
 static Material Make(string n,Color c){string p="Assets/ChemistryLab/"+n+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(p);if(!m){m=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(m,p);}m.color=c;return m;}
 static GameObject Part(Transform root,string n,Vector3 p,Vector3 scale,Material m,PrimitiveType type=PrimitiveType.Cube){var g=GameObject.CreatePrimitive(type);g.name=n;g.transform.SetParent(root,false);g.transform.localPosition=p;g.transform.localScale=scale;g.GetComponent<Renderer>().sharedMaterial=m;Object.DestroyImmediate(g.GetComponent<Collider>());return g;}
 static GameObject Item(Transform root,string name,string kind,Vector3 p){var g=new GameObject(name);g.transform.SetParent(root,false);g.transform.localPosition=p;g.AddComponent<Rigidbody>().isKinematic=true;g.AddComponent<SafetyWearable>().kind=kind;return g;}
 static void Finish(GameObject g,Vector3 center,Vector3 size){var c=g.AddComponent<BoxCollider>();c.center=center;c.size=size;g.AddComponent<XRGrabInteractable>();}
 [MenuItem("Chemistry Lab/Build Safety Station")]
 public static void Build(){var old=GameObject.Find("Safety station");if(old)Object.DestroyImmediate(old);var root=new GameObject("Safety station").transform;root.position=new Vector3(-4.8f,1.1f,-.8f);var white=Make("Coat cotton",new Color(.92f,.94f,.96f));var yellow=Make("Safety glove yellow",new Color(1,.73f,.03f));var black=Make("Safety frame",new Color(.045f,.08f,.1f));var blue=Make("Goggle lens",new Color(.45f,.75f,.82f));
 var coat=Item(root,"Önlük — E ile giy","coat",new Vector3(0,.65f,.3f));Part(coat.transform,"Cotton torso",Vector3.zero,new Vector3(.42f,.65f,.055f),white);for(int side=-1;side<=1;side+=2){var sleeve=Part(coat.transform,"Sleeve",new Vector3(side*.29f,.15f,0),new Vector3(.14f,.48f,.06f),white);sleeve.transform.localRotation=Quaternion.Euler(0,0,side*25);var lapel=Part(coat.transform,"Lapel",new Vector3(side*.065f,.2f,-.04f),new Vector3(.08f,.2f,.02f),white);lapel.transform.localRotation=Quaternion.Euler(0,0,side*22);Part(coat.transform,"Pocket",new Vector3(side*.12f,-.13f,-.04f),new Vector3(.10f,.12f,.015f),blue);}for(int i=0;i<4;i++)Part(coat.transform,"Button",new Vector3(0,.12f-i*.105f,-.04f),Vector3.one*.016f,black,PrimitiveType.Sphere);Finish(coat,Vector3.zero,new Vector3(.8f,.7f,.15f));
 Part(root,"Hanger stem",new Vector3(0,1.11f,.32f),new Vector3(.03f,.26f,.03f),black);for(int side=-1;side<=1;side+=2){var rail=Part(root,"Hanger",new Vector3(side*.13f,.99f,.32f),new Vector3(.29f,.025f,.025f),black);rail.transform.localRotation=Quaternion.Euler(0,0,side*-20);}
 var gloves=Item(root,"Sarı eldivenler — E ile giy","gloves",new Vector3(-.5f,.06f,-.12f));for(int side=-1;side<=1;side+=2){Part(gloves.transform,"Palm",new Vector3(side*.10f,0,0),new Vector3(.12f,.035f,.15f),yellow);for(int f=0;f<4;f++)Part(gloves.transform,"Finger",new Vector3(side*.10f+(f-1.5f)*.026f,0,.115f),new Vector3(.022f,.03f,.10f),yellow);Part(gloves.transform,"Thumb",new Vector3(side*.18f,0,.02f),new Vector3(.065f,.035f,.035f),yellow);}Finish(gloves,new Vector3(0,0,.04f),new Vector3(.45f,.12f,.3f));
 var goggles=Item(root,"Koruyucu gözlük — E ile tak","goggles",new Vector3(.5f,.08f,-.12f));for(int side=-1;side<=1;side+=2){Part(goggles.transform,"Frame",new Vector3(side*.075f,0,0),new Vector3(.14f,.08f,.055f),black);Part(goggles.transform,"Lens",new Vector3(side*.075f,0,-.03f),new Vector3(.115f,.058f,.01f),blue);Part(goggles.transform,"Strap",new Vector3(side*.15f,0,.055f),new Vector3(.018f,.025f,.16f),black);}Part(goggles.transform,"Bridge",Vector3.zero,new Vector3(.05f,.025f,.03f),black);Finish(goggles,Vector3.zero,new Vector3(.35f,.12f,.24f));
 var label=new GameObject("Safety station sign");label.transform.SetParent(root,false);label.transform.localPosition=new Vector3(0,1.42f,.3f);var t=label.AddComponent<TextMesh>();t.text="GÜVENLİK ALANI\nÖnlük • Eldiven • Gözlük\nE ile giy / XR: tutarak giy";t.fontSize=64;t.characterSize=.027f;t.anchor=TextAnchor.MiddleCenter;t.alignment=TextAlignment.Center;t.color=Color.white;
 var session=Object.FindFirstObjectByType<LabSession>();if(!session.GetComponent<LabSafety>())session.gameObject.AddComponent<LabSafety>();EditorSceneManager.MarkSceneDirty(root.gameObject.scene);EditorSceneManager.SaveOpenScenes();AssetDatabase.SaveAssets();}
}
}
